def transform(grid):
    """Connect separated foreground components with shortest Manhattan paths."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    labels = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or labels[r][c] >= 0:
                continue
            k = len(components)
            pts = []
            labels[r][c] = k
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                pts.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and labels[yy][xx] < 0:
                        labels[yy][xx] = k
                        stack.append((yy, xx))
            components.append(pts)
    n = len(components)
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            best = None
            for r1, c1 in components[i]:
                for r2, c2 in components[j]:
                    d = abs(r1-r2) + abs(c1-c2)
                    cand = (d, r1, c1, r2, c2)
                    if best is None or cand < best:
                        best = cand
            edges.append((best[0], i, j, best[1:]))
    out = [row[:] for row in grid]
    for d, i, j, (r1, c1, r2, c2) in sorted(edges):
        a, b = find(i), find(j)
        if a == b:
            continue
        parent[b] = a
        # Use an L path, vertical first then horizontal.
        sy = 1 if r2 >= r1 else -1
        for r in range(r1 + sy, r2 + sy, sy):
            if grid[r][c1] == bg:
                out[r][c1] = 2
        sx = 1 if c2 >= c1 else -1
        for c in range(c1 + sx, c2 + sx, sx):
            if grid[r2][c] == bg:
                out[r2][c] = 2
    return out

